-- Longest Increasing Subsequence (Medium)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$longest-increasing-subsequence$q$, $q$Longest Increasing Subsequence$q$, $q$A subsequence keeps the original order but may skip elements. Find the length of the longest strictly increasing subsequence of the array (each element larger than the one before it).$q$, $q$Medium$q$, $q$Dynamic Programming$q$, 'code', ARRAY[$q$dynamic-programming$q$, $q$binary-search$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: n.\n    # Line 2: n integers.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: n.\n// Line 2: n integers.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: n.\n        // Line 2: n integers.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: n.\n    // Line 2: n integers.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: n.\n    // Line 2: n integers.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "6\n10 9 2 5 3 7", "output": "3", "explanation": "For example 2, 5, 7 or 2, 3, 7."}, {"input": "4\n4 4 4 4", "output": "1", "explanation": "Strictly increasing: equal values do not extend a subsequence."}]$q$::jsonb, ARRAY[$q$1 ≤ n ≤ 10 000$q$, $q$-10^6 ≤ a[i] ≤ 10^6$q$]::text[], 25, 1013, 2000, 262144, $q$Line 1: n.
Line 2: n integers.$q$, $q$One integer, the length.$q$, $q$The O(n²) DP (dp[i] = 1 + max dp[j] for j < i with a[j] < a[i]) is too slow at n = 10 000 in slower languages. Keep an array tails where tails[k] is the smallest possible last value of an increasing subsequence of length k + 1. For each x, binary search the first tails entry ≥ x and replace it with x (append if none). The final length of tails is the answer. Use lower bound so equal values do not extend. O(n log n).$q$, false)
ON CONFLICT (slug) DO NOTHING;

